<?php
namespace App\Models\Landlord;
class SubscriptionVoucher extends LandlordModel { public const PERCENT='percent'; public const FIXED='fixed'; protected $fillable=['code','name','discount_type','discount_value','max_redemptions','starts_at','ends_at','is_active']; protected function casts(): array{return ['discount_value'=>'integer','max_redemptions'=>'integer','redemptions'=>'integer','starts_at'=>'datetime','ends_at'=>'datetime','is_active'=>'boolean'];} public function isUsable(): bool{return $this->is_active && ($this->starts_at===null||$this->starts_at->isPast()) && ($this->ends_at===null||$this->ends_at->isFuture()) && ($this->max_redemptions===null||$this->redemptions<$this->max_redemptions);} public function discountFor(int $amount): int{return min($amount,$this->discount_type===self::PERCENT?(int)floor($amount*$this->discount_value/100):$this->discount_value);} }